-- Offline ontwerpschema v1. Niet aangesloten op PicoT.
PRAGMA foreign_keys=ON;
CREATE TABLE definition(id INTEGER PRIMARY KEY, kind TEXT NOT NULL, external_id TEXT NOT NULL, version TEXT NOT NULL, payload_json TEXT NOT NULL, UNIQUE(kind,external_id,version));
CREATE TABLE local_day(id INTEGER PRIMARY KEY, local_date TEXT NOT NULL UNIQUE, start_us INTEGER NOT NULL, end_us INTEGER NOT NULL, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), year INTEGER NOT NULL, month INTEGER NOT NULL, iso_year INTEGER NOT NULL, iso_week INTEGER NOT NULL, weekday_ordinal INTEGER NOT NULL, quarter_count INTEGER NOT NULL CHECK(quarter_count IN (92,96,100)), calendar_def INTEGER NOT NULL REFERENCES definition(id));
CREATE TABLE context_version(id INTEGER PRIMARY KEY, scope_id INTEGER NOT NULL REFERENCES definition(id), effective_from_us INTEGER, observed_at_us INTEGER NOT NULL, previous_id INTEGER REFERENCES context_version(id), content_def INTEGER NOT NULL REFERENCES definition(id), time_quality TEXT NOT NULL);
CREATE TABLE provenance(id INTEGER PRIMARY KEY, source_def INTEGER NOT NULL REFERENCES definition(id), method_def INTEGER NOT NULL REFERENCES definition(id), context_id INTEGER REFERENCES context_version(id), evidence_digest TEXT, evidence_status TEXT NOT NULL, captured_us INTEGER NOT NULL);
CREATE TABLE quality(id INTEGER PRIMARY KEY, evidence_kind TEXT NOT NULL, coverage TEXT NOT NULL, validity TEXT NOT NULL, reason_def INTEGER REFERENCES definition(id), method_def INTEGER NOT NULL REFERENCES definition(id));
CREATE TABLE interval_value(scope_id INTEGER NOT NULL REFERENCES definition(id), metric_id INTEGER NOT NULL REFERENCES definition(id), start_us INTEGER NOT NULL, end_us INTEGER NOT NULL CHECK(end_us>start_us), revision INTEGER NOT NULL CHECK(revision>0), day_id INTEGER NOT NULL REFERENCES local_day(id), value REAL, quality_id INTEGER NOT NULL REFERENCES quality(id), provenance_id INTEGER NOT NULL REFERENCES provenance(id), recorded_us INTEGER NOT NULL, previous_revision INTEGER, PRIMARY KEY(scope_id,metric_id,start_us,end_us,revision)) WITHOUT ROWID;
CREATE INDEX interval_day_metric ON interval_value(day_id,metric_id,start_us);
CREATE TABLE interval_context(scope_id INTEGER NOT NULL REFERENCES definition(id), start_us INTEGER NOT NULL, end_us INTEGER NOT NULL, context_id INTEGER NOT NULL REFERENCES context_version(id), PRIMARY KEY(scope_id,start_us,end_us,context_id)) WITHOUT ROWID;
CREATE TABLE tariff(scope_id INTEGER NOT NULL REFERENCES definition(id), start_us INTEGER NOT NULL, end_us INTEGER NOT NULL, revision INTEGER NOT NULL, day_id INTEGER NOT NULL REFERENCES local_day(id), import_decimal TEXT, export_decimal TEXT, import_quality INTEGER NOT NULL REFERENCES quality(id), export_quality INTEGER NOT NULL REFERENCES quality(id), contract_def INTEGER NOT NULL REFERENCES definition(id), provenance_id INTEGER NOT NULL REFERENCES provenance(id), recorded_us INTEGER NOT NULL, previous_revision INTEGER, PRIMARY KEY(scope_id,start_us,end_us,revision)) WITHOUT ROWID;
CREATE INDEX tariff_day ON tariff(day_id,start_us);
CREATE TABLE day_value(scope_id INTEGER NOT NULL REFERENCES definition(id), day_id INTEGER NOT NULL REFERENCES local_day(id), metric_id INTEGER NOT NULL REFERENCES definition(id), revision INTEGER NOT NULL, value REAL, partial_value REAL, expected_intervals INTEGER NOT NULL, usable_intervals INTEGER NOT NULL, quality_id INTEGER NOT NULL REFERENCES quality(id), provenance_id INTEGER NOT NULL REFERENCES provenance(id), recorded_us INTEGER NOT NULL, previous_revision INTEGER, PRIMARY KEY(scope_id,day_id,metric_id,revision)) WITHOUT ROWID;
CREATE TABLE coverage_span(id INTEGER PRIMARY KEY, scope_id INTEGER NOT NULL REFERENCES definition(id), metric_id INTEGER NOT NULL REFERENCES definition(id), day_id INTEGER NOT NULL REFERENCES local_day(id), start_us INTEGER NOT NULL, end_us INTEGER NOT NULL, value_revision INTEGER NOT NULL, quality_id INTEGER NOT NULL REFERENCES quality(id), provenance_id INTEGER NOT NULL REFERENCES provenance(id));
CREATE TABLE day_close(scope_id INTEGER NOT NULL REFERENCES definition(id), day_id INTEGER NOT NULL REFERENCES local_day(id), revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('OPEN','CLOSING','CLOSED_COMPLETE','CLOSED_PARTIAL')), checked_until_us INTEGER, recorded_us INTEGER NOT NULL, manifest_def INTEGER NOT NULL REFERENCES definition(id), previous_revision INTEGER, PRIMARY KEY(scope_id,day_id,revision)) WITHOUT ROWID;
CREATE TABLE financial_result(scope_id INTEGER NOT NULL REFERENCES definition(id), day_id INTEGER NOT NULL REFERENCES local_day(id), metric_id INTEGER NOT NULL REFERENCES definition(id), revision INTEGER NOT NULL, amount_decimal TEXT, original_payload TEXT, provenance_id INTEGER NOT NULL REFERENCES provenance(id), quality_id INTEGER NOT NULL REFERENCES quality(id), recorded_us INTEGER NOT NULL, previous_revision INTEGER, PRIMARY KEY(scope_id,day_id,metric_id,revision)) WITHOUT ROWID;
CREATE TABLE evidence_object(digest TEXT PRIMARY KEY, kind TEXT NOT NULL, relative_path TEXT, stored_bytes INTEGER, status TEXT NOT NULL, created_us INTEGER, source_def INTEGER NOT NULL REFERENCES definition(id));
CREATE TABLE evidence_edge(parent_digest TEXT NOT NULL REFERENCES evidence_object(digest), child_digest TEXT NOT NULL REFERENCES evidence_object(digest), relation TEXT NOT NULL, PRIMARY KEY(parent_digest,child_digest,relation)) WITHOUT ROWID;
CREATE TABLE plan_evidence(plan_id TEXT PRIMARY KEY, snapshot_id TEXT, evaluation_id TEXT, valid_from_us INTEGER, valid_until_us INTEGER, object_digest TEXT REFERENCES evidence_object(digest), availability TEXT NOT NULL, admission_evidence_digest TEXT REFERENCES evidence_object(digest));
CREATE TABLE event(id TEXT PRIMARY KEY, kind TEXT NOT NULL, effective_us INTEGER, observed_us INTEGER NOT NULL, plan_id TEXT, provenance_id INTEGER NOT NULL REFERENCES provenance(id), payload_json TEXT NOT NULL);
CREATE TABLE gap_episode(id TEXT PRIMARY KEY, scope_id INTEGER NOT NULL REFERENCES definition(id), metric_id INTEGER NOT NULL REFERENCES definition(id), start_us INTEGER NOT NULL, end_us INTEGER NOT NULL, cause TEXT NOT NULL, state TEXT NOT NULL, provenance_id INTEGER NOT NULL REFERENCES provenance(id));
CREATE TABLE gap_observation(gap_id TEXT NOT NULL REFERENCES gap_episode(id), evidence_digest TEXT NOT NULL, observed_us INTEGER NOT NULL, payload_json TEXT NOT NULL, PRIMARY KEY(gap_id,evidence_digest)) WITHOUT ROWID;
CREATE TABLE cursor(source_key TEXT PRIMARY KEY, file_identity TEXT, offset_bytes INTEGER, proved_until_us INTEGER, last_batch TEXT, state TEXT NOT NULL);
CREATE TABLE retention_batch(id TEXT PRIMARY KEY, created_us INTEGER NOT NULL, policy_def INTEGER NOT NULL REFERENCES definition(id), manifest_json TEXT NOT NULL, state TEXT NOT NULL);
